// The carousel of a container composition of dekker-lib (eds.config.ts `carousels`): the design
// system's SplideCarouselController on the composition's class, with the options its Storybook story
// gives. The page-controller runner hands a controller one options object; SplideCarouselController
// takes the class and the Splide options apart, so this class splits them. `breakpoints` names one of
// the presets splide-carousel-controller.js exports (responsiveSlidesThree), or is the object itself.
// Generated by tools/eds-build/eds-config.cjs.
import * as splide from './splide-carousel-controller.js';

export class SplideCompositionController {
  /**
   * @param {{ carouselClass: string, breakpoints?: string | Record<string, unknown> } & Record<string, unknown>} options
   */
  constructor({ carouselClass, breakpoints, ...options }) {
    this.carouselClass = carouselClass;
    const presets = /** @type {Record<string, unknown>} */ (/** @type {unknown} */ (splide));
    this.options = {
      ...options,
      ...(breakpoints ? { breakpoints: typeof breakpoints === 'string' ? presets[breakpoints] : breakpoints } : {}),
    };
  }

  init() {
    new splide.SplideCarouselController(this.carouselClass, this.options).init();
  }
}
